# find triangle closures: edge (a,b) at t3 where exists c with (a,c) t1 and (b,c) t2, t3 >= max(t1,t2), t3-max(t1,t2)<=800
import collections
def analyze(lo,hi,delta=800):
    win=[e for e in events if lo<=e[2]<=hi]
    # adjacency first-contact times (all events, but restrict supports to <= t3, within window)
    closures=[]
    # build list of (neighbor, t) per node from window events
    adj=collections.defaultdict(list)
    for u,v,t in win:
        adj[u].append((v,t)); adj[v].append((u,t))
    for u,v,t3 in win:
        # common neighbors c
        cu={}
        for c,t in adj[u]:
            if t<=t3 and c!=v:
                cu[c]=max(cu.get(c,-1),t) if False else min(cu.get(c,10**9),t)
        best=None
        for c,t in adj[v]:
            if t<=t3 and c!=u and c in cu:
                lag=t3-max(cu[c],t)
                # use min support times -> lag = t3 - max(first_u_c, first_v_c) approximated
                if lag<=delta and lag>=0:
                    if best is None or lag<best[1]: best=(c,lag)
        if best: closures.append((u,v,t3,best[0],best[1]))
    return win,closures
win,cl=analyze(22553,34553)
print("window events",len(win),"closures",len(cl))
cand=set([18,23,26,35,42,62,64,68,80,98,102,149])
clc=[c for c in cl if c[0] in cand or c[1] in cand]
print("cand closures",len(clc))
for c in cl[:25]: print(c)

